    76	\section{The pulled-apart measurements and observables}
    77	
    78	The measurement $\{\hat{S}_{g_X,g_Z}\}$ reads out an $X$-polynomial and a $Z$-polynomial simultaneously. We now separate the two readings again, this time as commuting actions on distinct registers: the polynomial outcome is measured on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), while a genuine Pauli measurement acts on the EPR register $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
    79	
    80	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
    81		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly}
    82		\leanok
    83		\uses{lem:qld-4-7}
    84		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
    85		\[
    86			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
    87			\qquad \text{and} \qquad
    88			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
    89		\]
    90		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$.
    91	\end{definition}
    92	
    93	\begin{lemma}[Projectivity of the single-basis marginals]\label{lem:s-w-marginals-projective}
    94		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly_isProjective}
    95		\leanok
    96		\uses{def:s-w-marginals, lem:qld-4-7}
    97		For each $W\in\{X,Z\}$, the family $\{\hat{S}^W_g\}_g$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
    98	\end{lemma}
