   100	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
   101		\lean{MIPStarRE.QPBT.tauDotProj}
   102		\leanok
   103		\uses{def:generalized-pauli}
   104		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the operator
   105		\begin{equation}\label{eq:def-tauwu}
   106			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
   107		\end{equation}
   108	\end{definition}
   109	
   110	\begin{lemma}[Projectivity and completeness of the dot-product operators]\label{lem:tau-dot-product-projective}
   111		\lean{MIPStarRE.QPBT.tauDotProj_isProj, MIPStarRE.QPBT.sum_tauDotProj_eq_one}
   112		\leanok
   113		\uses{def:tau-dot-product-projector, def:generalized-pauli}
   114		For each fixed $W$ and $\tilde{u}$, every $\tau^W_a(\tilde{u})$ is a projector and
   115		$\sum_{a\in\F_q}\tau^W_a(\tilde{u})=\Id$. Thus
   116		$\{\tau^W_a(\tilde{u})\}_{a\in\F_q}$ is a projective measurement.
   117	\end{lemma}
   118	
   119	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
   120		\lean{MIPStarRE.QPBT.tildeM}
   121		\leanok
   122		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:qld-full-field-decoder}
   123		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
   124		\begin{equation}\label{eq:tilde_M}
   125			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
   126		\end{equation}
   127		the sum ranging over $g \in \mathrm{ideg}_{d,m}(\F_q)$. If $\hat{S}^W_g$ is viewed as an operator acting on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), then $\tilde{M}^{W,\tilde{u}}_a$ acts on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ (resp.\ $\mathrm{B}\mathrm{B}'\mathrm{B}''$), the $\tau^W$ factor acting on $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
   128	\end{definition}
   129	
   130	\begin{lemma}[Projectivity and completeness of the pulled-apart measurements]\label{lem:tilde-m-projective}
   131		\lean{MIPStarRE.QPBT.tildeM_isProj, MIPStarRE.QPBT.sum_tildeM_eq_one}
   132		\leanok
   133		\uses{def:tilde-m-measurement, lem:s-w-marginals-projective,
   134			lem:tau-dot-product-projective}
   135		For each $W$ and $\tilde{u}$, every $\tilde{M}^{W,\tilde{u}}_a$ is a projector and
   136		$\sum_{a\in\F_q}\tilde{M}^{W,\tilde{u}}_a=\Id$. Thus
   137		$\{\tilde{M}^{W,\tilde{u}}_a\}_{a\in\F_q}$ is a projective measurement.
   138	\end{lemma}
